import java.util.Optional;

/**
 * requestId 幂等记录端口。
 *
 * <p>主张(claim)与业务处理在同一事务内：先插入主张行占用 requestId，
 * 业务完成后回填首次响应；并发同键插入触发主键冲突后重新读取判定重放或 409。</p>
 */
public interface IdempotencyPort {

    /** 查询已存在的幂等记录。 */
    Optional<IdempotencyRow> find(String requestId);

    /**
