1	package com.example.starter.cosmetic.service;
2	
3	import com.example.starter.cosmetic.AbstractCosmeticIntegrationTest;
4	import com.example.starter.cosmetic.domain.FilingStatus;
5	import com.example.starter.cosmetic.port.FilingPort;
6	import com.example.starter.cosmetic.testsupport.FilingFixtures;
7	import com.example.starter.cosmetic.web.dto.ChangeFilingRequest;
8	import com.example.starter.cosmetic.web.dto.FilingResponse;
9	import com.example.starter.cosmetic.web.dto.FilingResultResponse;
10	import com.example.starter.cosmetic.web.dto.FormulationItemRequest;
11	import com.example.starter.cosmetic.web.dto.SubmitFilingRequest;
12	import com.example.starter.cosmetic.web.dto.TestReportRequest;
13	import org.junit.jupiter.api.Test;
14	import org.springframework.beans.factory.annotation.Autowired;
15	
16	import java.math.BigDecimal;
17	import java.time.Instant;
18	import java.time.LocalDate;
19	import java.util.List;
20	
21	import static org.assertj.core.api.Assertions.assertThat;
22	import static org.assertj.core.api.Assertions.assertThatThrownBy;
23	
24	/**
25	 * 备案主生命周期 H2 集成测试：提交/形式审查/公示第10日期满/生效、
26	 * 报告3年恰满、浓度恰等、实质变更重新审查、简易变更引用原编号、
27	 * 幂等重放与同键异参409、注销终态、历史链与审查明细复算。
28	 */
29	class FilingLifecycleIntegrationTest extends AbstractCosmeticIntegrationTest {
30	
31	    @Autowired
32	    private FilingService filingService;
33	
34	    @Autowired
35	    private FilingPort filingPort;
36	
37	    private static final Instant EXPIRES_EXPECTED = Instant.parse("2026-07-10T00:00:00Z");
38	
39	    private SubmitFilingRequest ordinary(String requestId, String product) {
40	        return FilingFixtures.ordinarySubmit(requestId, product);
41	    }
42	
43	    @Test
44	    void ordinarySubmissionPassesFormReviewAndEntersPublicity() {
45	        FilingResultResponse result = filingService.submit(ordinary("REQ-1", "P-ORD-1"));
46	
47	        assertThat(result.filing().status()).isEqualTo(FilingStatus.PUBLIC.name());
48	        assertThat(result.filing().filingNo()).isEqualTo("SYN-F-000001");
49	        assertThat(result.filing().publicNoticeDateUtc()).isEqualTo(LocalDate.of(2026, 6, 30));
50	        assertThat(result.filing().publicExpiresAtUtc()).isEqualTo(EXPIRES_EXPECTED);
51	        assertThat(result.reviewDetails()).isNotEmpty();
52	        assertThat(filingPort.findActiveSlot("P-ORD-1")).isEmpty();
53	    }
54	
55	    @Test
56	    void publicityExpiresExactlyAtDayTenMidnightUtc() {
57	        FilingResultResponse submitted = filingService.submit(ordinary("REQ-2", "P-EXP-1"));
58	        String filingNo = submitted.filing().filingNo();
59	
60	        // 期满前 1 纳秒不生效
61	        clock.setInstant(EXPIRES_EXPECTED.minusNanos(1));
62	        assertThat(filingService.expireDuePublicNotices(null)).isZero();
63	        assertThat(filingService.getFiling(filingNo).status()).isEqualTo(FilingStatus.PUBLIC.name());
64	
65	        // 恰第 10 日 24:00（=D+10 00:00 UTC）期满自动生效
66	        clock.setInstant(EXPIRES_EXPECTED);
67	        int effected = filingService.expireDuePublicNotices(null);
68	
69	        assertThat(effected).isEqualTo(1);
70	        FilingResponse effective = filingService.getFiling(filingNo);
71	        assertThat(effective.status()).isEqualTo(FilingStatus.EFFECTIVE.name());
72	        assertThat(effective.effectiveAtUtc()).isEqualTo(EXPIRES_EXPECTED);
73	        assertThat(filingPort.findActiveSlot("P-EXP-1")).isPresent();
74	        assertThat(filingPort.findActiveSlot("P-EXP-1").orElseThrow().filingNo()).isEqualTo(filingNo);
75	    }
76	
77	    @Test
78	    void specialReportExactlyThreeYearsOldAndConcentrationAtLimitPasses() {
79	        SubmitFilingRequest request = FilingFixtures.sunscreenSubmit(
80	                "REQ-3", "P-SUN-1", LocalDate.of(2023, 6, 30), true);
81	
82	        FilingResultResponse result = filingService.submit(request);
83	
84	        assertThat(result.filing().status()).isEqualTo(FilingStatus.PUBLIC.name());
85	        assertThat(result.reviewDetails())
86	                .anyMatch(d -> d.ruleCode().equals("REPORT_VALIDITY") && d.passed())
87	                .anyMatch(d -> d.ruleCode().equals("RESTRICTED_CONCENTRATION") && d.passed());
88	    }
89	
90	    @Test
91	    void specialReportOneDayExpiredRejected() {
92	        SubmitFilingRequest request = FilingFixtures.sunscreenSubmit(
93	                "REQ-4", "P-SUN-2", LocalDate.of(2023, 6, 29), true);
94	
95	        FilingResultResponse result = filingService.submit(request);
96	
97	        assertThat(result.filing().status()).isEqualTo(FilingStatus.FORM_REJECTED.name());
98	        assertThat(result.filing().rejectReason()).contains("REPORT_VALIDITY");
99	        assertThat(filingPort.findActiveSlot("P-SUN-2")).isEmpty();
100	    }
101	
102	    @Test
103	    void unsupportedClaimRejectedAtFormReview() {
104	        SubmitFilingRequest request = new SubmitFilingRequest("REQ-5", "P-BAD", "违规产品",
105	                FilingFixtures.ordinaryFormulation(), List.of("MEDICAL_CURE"), List.of());
106	
107	        FilingResultResponse rejected = filingService.submit(request);
108	
109	        assertThat(rejected.filing().status()).isEqualTo(FilingStatus.FORM_REJECTED.name());
110	        assertThat(rejected.filing().rejectReason()).contains("不支持的功效宣称");
111	    }
112	
113	    @Test
114	    void sameRequestIdSameParamsReplaysFirstResult() {
115	        FilingResultResponse first = filingService.submit(ordinary("REQ-IDEM-1", "P-IDEM-1"));
116	        FilingResultResponse replay = filingService.submit(ordinary("REQ-IDEM-1", "P-IDEM-1"));
117	
118	        assertThat(replay.idempotentReplay()).isTrue();
119	        assertThat(replay.filing().filingNo()).isEqualTo(first.filing().filingNo());
120	        assertThat(replay.atUtc()).isEqualTo(first.atUtc());
121	        assertThat(filingPort.findByProduct("P-IDEM-1")).hasSize(1);
122	    }
123	
124	    @Test
125	    void sameRequestIdDifferentParamsReturnsConflict() {
126	        filingService.submit(ordinary("REQ-IDEM-2", "P-IDEM-2"));
127	
128	        SubmitFilingRequest changed = new SubmitFilingRequest("REQ-IDEM-2", "P-IDEM-2", "改名产品",
129	                FilingFixtures.ordinaryFormulation(), List.of("MOISTURIZING"), List.of());
130	
131	        assertThatThrownBy(() -> filingService.submit(changed))
132	                .isInstanceOf(ConflictException.class)
133	                .hasMessageContaining("409");
134	        assertThat(filingPort.findByProduct("P-IDEM-2")).hasSize(1);
135	    }
136	
137	    @Test
138	    void simplePackagingChangeKeepsFilingNoAndSwitchesVersionAtomically() {
139	        // 先生效
140	        FilingResultResponse submitted = filingService.submit(ordinary("REQ-SC-1", "P-SIMPLE-1"));
141	        clock.setInstant(EXPIRES_EXPECTED);
142	        filingService.expireDuePublicNotices(null);
143	
144	        ChangeFilingRequest change = FilingFixtures.packagingChange("REQ-SC-2", "新包装文字：请置于阴凉处");
145	        FilingResultResponse result = filingService.change("P-SIMPLE-1", change);
146	
147	        String filingNo = submitted.filing().filingNo();
148	        assertThat(result.filing().changeType()).isEqualTo("SIMPLE");
149	        assertThat(result.filing().status()).isEqualTo(FilingStatus.EFFECTIVE.name());
150	        assertThat(result.filing().filingNo()).isEqualTo(filingNo);
151	        assertThat(result.filing().versionNo()).isEqualTo(2);
152	        assertThat(result.filing().parentFilingNo()).isEqualTo(filingNo);
153	        assertThat(result.filing().packagingText()).contains("新包装文字");
154	
155	        // 同事务：旧版本 SUPERSEDED，槽位指向新版本
156	        assertThat(filingPort.findVersion(filingNo, 1).orElseThrow().status())
157	                .isEqualTo(FilingStatus.SUPERSEDED);
158	        assertThat(filingPort.findActiveSlot("P-SIMPLE-1").orElseThrow().versionNo()).isEqualTo(2);
159	    }
160	
161	    @Test
162	    void substantiveChangeTriggersNewFilingNoReReviewAndAtomicSwitchOnExpiry() {
163	        // 原普通备案生效
164	        filingService.submit(ordinary("REQ-SUB-1", "P-SUBST-1"));
165	        clock.setInstant(EXPIRES_EXPECTED);
166	        filingService.expireDuePublicNotices(null);
167	
168	        // 实质变更：新增防晒宣称（配方也变化），须重新审查并生成新备案编号
169	        List<FormulationItemRequest> newFormulation = FilingFixtures.sunscreenFormulation();
170	        List<TestReportRequest> newReports = List.of(
171	                FilingFixtures.sunscreenReport("R-SUB-1", LocalDate.of(2025, 1, 1), true));
172	        ChangeFilingRequest change = new ChangeFilingRequest("REQ-SUB-2", null,
173	                newFormulation, List.of("MOISTURIZING", "SUNSCREEN"), newReports, "包装不变");
174	
175	        FilingResultResponse changed = filingService.change("P-SUBST-1", change);
176	
177	        String oldNo = "SYN-F-000001";
178	        String newNo = "SYN-F-000002";
179	        assertThat(changed.filing().filingNo()).isEqualTo(newNo);
180	        assertThat(changed.filing().parentFilingNo()).isEqualTo(oldNo);
181	        assertThat(changed.filing().changeType()).isEqualTo("SUBSTANTIVE");
182	        assertThat(changed.filing().status()).isEqualTo(FilingStatus.PUBLIC.name());
183	        // 新版本公示期间旧备案仍有效
184	        assertThat(filingPort.findVersion(oldNo, 1).orElseThrow().status())
185	                .isEqualTo(FilingStatus.EFFECTIVE);
186	        assertThat(filingPort.findActiveSlot("P-SUBST-1").orElseThrow().filingNo()).isEqualTo(oldNo);
187	
188	        // 新版本公示期满：同事务新版本生效 + 旧版本 SUPERSEDED + 槽位切换
189	        Instant newExpires = changed.filing().publicExpiresAtUtc();
190	        clock.setInstant(newExpires);
191	        filingService.expireDuePublicNotices(null);
192	
193	        assertThat(filingPort.findVersion(newNo, 2).orElseThrow().status())
194	                .isEqualTo(FilingStatus.EFFECTIVE);
