27	class FilingHttpIntegrationTest extends AbstractCosmeticIntegrationTest {
28	
29	    @Autowired
30	    private WebApplicationContext context;
31	
32	    @Autowired
33	    private ObjectMapper objectMapper;
34	
35	    private MockMvc mockMvc;
36	
37	    @org.junit.jupiter.api.BeforeEach
38	    void setupMvc() {
39	        this.mockMvc = MockMvcBuilders.webAppContextSetup(context)
40	                .addFilters(new CharacterEncodingFilter("UTF-8", true))
41	                .build();
42	    }
43	
44	    private String submitJson(String requestId, String product, String name, List<String> claims) {
45	        return """
46	                {
47	                  "requestId": "%s",
48	                  "productCode": "%s",
49	                  "productName": "%s",
50	                  "formulation": [
51	                    {"code": "WATER", "name": "水", "concentrationPct": 78.0000},
52	                    {"code": "GLYCERIN", "name": "甘油", "concentrationPct": 5.0000}
53	                  ],
54	                  "claims": %s,
55	                  "reports": []
56	                }
57	                """.formatted(requestId, product, name, claimsJson(claims));
58	    }
59	
60	    private String claimsJson(List<String> claims) {
61	        return objectMapper.valueToTree(claims).toString();
62	    }
63	
64	    @Test
65	    void fullHttpLifecycle_submitConflictExpiryChangeObjectionWithdraw() throws Exception {
66	        // 1. 首次备案提交：200，进入公示
67	        mockMvc.perform(post("/api/filings")
68	                        .contentType(MediaType.APPLICATION_JSON)
69	                        .content(submitJson("REQ-HTTP-1", "P-HTTP-1", "合成保湿乳", List.of("MOISTURIZING"))))
70	                .andExpect(status().isOk())
71	                .andExpect(jsonPath("$.filing.status").value("PUBLIC"))
72	                .andExpect(jsonPath("$.filing.filingNo").value("SYN-F-000001"))
73	                .andExpect(jsonPath("$.filing.publicExpiresAtUtc").value("2026-07-10T00:00:00Z"));
74	
75	        // 2. 同键异参：409
76	        mockMvc.perform(post("/api/filings")
77	                        .contentType(MediaType.APPLICATION_JSON)
78	                        .content(submitJson("REQ-HTTP-1", "P-HTTP-1", "改名产品", List.of("MOISTURIZING"))))
79	                .andExpect(status().isConflict())
80	                .andExpect(jsonPath("$.code").value("IDEMPOTENCY_PARAM_MISMATCH"));
81	
82	        // 3. 同键同参重放：200，idempotentReplay=true
83	        mockMvc.perform(post("/api/filings")
84	                        .contentType(MediaType.APPLICATION_JSON)
85	                        .content(submitJson("REQ-HTTP-1", "P-HTTP-1", "合成保湿乳", List.of("MOISTURIZING"))))
86	                .andExpect(status().isOk())
87	                .andExpect(jsonPath("$.idempotentReplay").value(true));
88	
89	        // 4. 恰第10日24:00 UTC 期满生效
90	        mockMvc.perform(post("/api/filings/public-notice-expiry")
91	                        .param("atUtc", "2026-07-10T00:00:00Z"))
92	                .andExpect(status().isOk())
93	                .andExpect(jsonPath("$.effected").value(1));
94	
95	        mockMvc.perform(get("/api/filings/SYN-F-000001"))
96	                .andExpect(status().isOk())
97	                .andExpect(jsonPath("$.status").value("EFFECTIVE"));
98	
99	        // 5. 简易变更（包装文字）：引用原编号、即时生效、v2
100	        String changeJson = """
101	                {
102	                  "requestId": "REQ-HTTP-2",
103	                  "productName": null,
104	                  "formulation": null,
105	                  "claims": null,
106	                  "reports": null,
107	                  "packagingText": "新包装：避免阳光直射"
108	                }
109	                """;
110	        mockMvc.perform(post("/api/filings/products/P-HTTP-1/changes")
111	                        .contentType(MediaType.APPLICATION_JSON)
112	                        .content(changeJson))
113	                .andExpect(status().isOk())
114	                .andExpect(jsonPath("$.filing.changeType").value("SIMPLE"))
115	                .andExpect(jsonPath("$.filing.filingNo").value("SYN-F-000001"))
116	                .andExpect(jsonPath("$.filing.versionNo").value(2))
117	                .andExpect(jsonPath("$.filing.status").value("EFFECTIVE"));
118	
119	        // 历史链：两版本
120	        mockMvc.perform(get("/api/filings/products/P-HTTP-1/history"))
121	                .andExpect(status().isOk())
122	                .andExpect(jsonPath("$.length()").value(2));
123	
124	        // 审查明细可复算
125	        mockMvc.perform(get("/api/filings/SYN-F-000001/reviews").param("versionNo", "1"))
126	                .andExpect(status().isOk())
127	                .andExpect(jsonPath("$.length()").value(org.hamcrest.Matchers.greaterThanOrEqualTo(4)));
128	
129	        // 6. 注销终态
130	        mockMvc.perform(post("/api/filings/SYN-F-000001/withdrawal")
131	                        .param("requestId", "REQ-HTTP-3")
132	                        .param("reason", "企业主动注销"))
133	                .andExpect(status().isOk())
134	                .andExpect(jsonPath("$.filing.status").value("WITHDRAWN"));
