136	        // 7. 重复注销幂等成功
137	        mockMvc.perform(post("/api/filings/SYN-F-000001/withdrawal")
138	                        .param("requestId", "REQ-HTTP-3")
139	                        .param("reason", "企业主动注销"))
140	                .andExpect(status().isOk())
141	                .andExpect(jsonPath("$.filing.status").value("WITHDRAWN"));
142	
143	        // 8. 注销后新宣称审查拒绝：形式驳回
144	        mockMvc.perform(post("/api/filings")
145	                        .contentType(MediaType.APPLICATION_JSON)
146	                        .content(submitJson("REQ-HTTP-4", "P-HTTP-1", "合成保湿乳", List.of("MOISTURIZING"))))
147	                .andExpect(status().isOk())
148	                .andExpect(jsonPath("$.filing.status").value("FORM_REJECTED"))
149	                .andExpect(jsonPath("$.filing.rejectReason").value(
150	                        org.hamcrest.Matchers.containsString("注销后新宣称审查一律拒绝")));
151	    }
152	
153	    @Test
154	    void publicityObjectionRaceViaHttp_objectionWinsBeforeExpiry() throws Exception {
155	        mockMvc.perform(post("/api/filings")
156	                        .contentType(MediaType.APPLICATION_JSON)
