package com.example.starter.cosmetic.child.domain;

/**
 * 儿童备案生命周期状态。
 *
 * <p>流转：提交(SUBMITTED，同步完成形式审查，实际不停留)→通过进公示(PUBLIC)，
 * 不通过 FORM_REJECTED；公示期满生效(EFFECTIVE)；材料补正生成新修订并使旧修订
 * 失效(VOID)；实质变更新版本生效后旧有效版本 SUPERSEDED。</p>
 */
public enum ChildFilingStatus {

    /** 已提交，形式审查尚未完成（中间态，提交时同步完成形式审查）。 */
    SUBMITTED(false),
    /** 形式审查驳回：分龄资料任一缺项一次列全，零生效，可在补正后生成新修订。 */
    FORM_REJECTED(true),
    /** 公示中：公示期为起算日起 10 个自然日，第 10 日 24:00(UTC) 期满；仅最新修订可公示。 */
    PUBLIC(false),
    /** 生效：该产品当前唯一有效的儿童备案。 */
    EFFECTIVE(false),
    /** 旧有效版本被实质变更新版本替代（同事务）。 */
    SUPERSEDED(true),
    /** 旧修订因材料补正生成新修订而失效（待审/被驳回修订原子置为失效）。 */
    VOID(true);

    private final boolean terminal;

    ChildFilingStatus(boolean terminal) {
        this.terminal = terminal;
    }

    /** 是否终态：终态修订不再发生状态迁移。 */
    public boolean isTerminal() {
        return terminal;
    }
}

package com.example.starter.cosmetic.child.domain;

/**
 * 儿童备案变更类型。
 */
public enum ChildChangeType {

    /** 首次儿童备案。 */
    INITIAL,
    /** 材料补正：形式审查驳回后补齐分龄资料，沿用同号生成新修订。 */
    CORRECTION,
    /** 实质变更：儿童属性、年龄区间、适用年龄标识范围、配方或儿童功效变化，重新审查公示并生成新编号。 */
    SUBSTANTIVE,
    /** 简易变更：仅包装文字（含产品名称文字）调整，不重新公示。 */
    SIMPLE
}

package com.example.starter.cosmetic.child.domain;

import java.math.BigDecimal;

/**
 * 儿童安全评价报告（合成数据，区别于成人功效评价试验报告）。
 *
 * <p>每个分档需独立的安全报告；成人功效报告不能替代儿童安全报告。
 * 报告必须明确覆盖申请年龄范围（在其分档内的申请年龄段）。</p>
