    t2.start();
    start.countDown();
    t1.join(15_000);
    t2.join(15_000);

    assertThat(error.get()).as("第 %d 轮无未预期异常: %s", r, error.get()).isNull();
    assertThat(expiryWins.get() + correctionWins.get())
            .as("第 %d 轮期满与补正必须恰好一个获胜", r).isEqualTo(1);

